$employee = $row['employee_snapshot'];
$calculation = $row['calculation_snapshot'];
$thaiMonths = [1 => 'มกราคม', 2 => 'กุมภาพันธ์', 3 => 'มีนาคม', 4 => 'เมษายน', 5 => 'พฤษภาคม', 6 => 'มิถุนายน', 7 => 'กรกฎาคม', 8 => 'สิงหาคม', 9 => 'กันยายน', 10 => 'ตุลาคม', 11 => 'พฤศจิกายน', 12 => 'ธันวาคม'];
$periodParts = explode('-', (string) $row['period_code']);
$periodLabel = ($thaiMonths[(int) ($periodParts[1] ?? 0)] ?? $row['period_code']) . ' ' . ((int) ($periodParts[0] ?? 0) + 543);
$organizationName = trim((string) ($organization['company_name'] ?? '')) ?: 'ไม่ระบุหน่วยงาน';
$createdTimestamp = strtotime((string) ($row['period_created_at'] ?? ''));
$issuedDate = $createdTimestamp ? date('d/m/', $createdTimestamp) . ((int) date('Y', $createdTimestamp) + 543) : '—';
$formatThaiDate = static function ($value): string {
    $timestamp = $value ? strtotime((string) $value) : false;
    return $timestamp ? date('d/m/', $timestamp) . ((int) date('Y', $timestamp) + 543) : '—';
};
