<section class="table-responsive mb-3"><table class="table table-bordered align-middle payslip-lines mb-0"><thead class="table-light"><tr><th>รายรับ</th><th class="text-end">จำนวนเงิน (บาท)</th><th>รายการหัก</th><th class="text-end">จำนวนเงิน (บาท)</th></tr></thead><tbody><?php $earnings = $calculation['earnings'] ?? []; $deductions = $calculation['deductions'] ?? []; $lineCount = max(count($earnings), count($deductions), 1); for ($index = 0; $index < $lineCount; $index++): $earning = $earnings[$index] ?? null; $deduction = $deductions[$index] ?? null; ?><tr><td><?= $earning ? Html::encode($earning['name']) : '' ?></td><td class="text-end"><?= $earning ? number_format($earning['amount'], 2) : '' ?></td><td><?= $deduction ? Html::encode($deduction['name']) : '' ?></td><td class="text-end"><?= $deduction ? number_format($deduction['amount'], 2) : '' ?></td></tr><?php endfor; ?></tbody><tfoot class="table-light fw-semibold"><tr><td>รวมรายรับ</td><td class="text-end"><?= number_format($row['gross_amount'], 2) ?></td><td>รวมรายการหัก</td><td class="text-end"><?= number_format($row['deduction_amount'], 2) ?></td></tr></tfoot></table></section>
